function gradeReaction(ms){
  ms=+ms; if(isNaN(ms)) return {error:'请输入毫秒'};
  var g; if(ms<200) g='超凡（<200ms）'; else if(ms<250) g='优秀（200–250ms）';
  else if(ms<300) g='良好（250–300ms）'; else if(ms<350) g='一般（300–350ms）';
  else g='可练习（≥350ms）';
  return {ms:ms, grade:g};
}
function tapsPerSec(taps, seconds){ taps=+taps; seconds=(+seconds)||1; if(!(taps>=0)) return {error:'点击数无效'}; return {taps:taps, seconds:seconds, tps:Math.round(taps/seconds*100)/100}; }
var EXPORTS={gradeReaction:gradeReaction, tapsPerSec:tapsPerSec};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TapGameForgePure = EXPORTS; }
